<h1 class="h3"><?= empty($trip['id']) ? 'Proposer un trajet' : 'Modifier le trajet' ?></h1><?php foreach ($errors ?? [] as $error): ?><div class="alert alert-danger" role="alert"><?= e($error) ?></div><?php endforeach; ?>
<div class="form-card mb-3">Contact : <?= e(($contact ?? $user)['first_name'] . ' ' . ($contact ?? $user)['last_name']) ?> — <?= e(($contact ?? $user)['email']) ?> — <?= e(($contact ?? $user)['phone']) ?></div>
<form action="<?= e($action) ?>" method="post" class="form-card"><?= token() ?><div class="row g-3"><div class="col-md-6"><label for="departure" class="form-label">Agence de départ</label><select name="departure_agency_id" id="departure" class="form-select" required><option value="">Choisir</option><?php foreach ($agencies as $agency): ?><option value="<?= (int) $agency['id'] ?>" <?= (string) ($trip['departure_agency_id'] ?? '') === (string) $agency['id'] ? 'selected' : '' ?>><?= e($agency['name']) ?></option><?php endforeach; ?></select></div><div class="col-md-6"><label for="arrival" class="form-label">Agence d’arrivée</label><select name="arrival_agency_id" id="arrival" class="form-select" required><option value="">Choisir</option><?php foreach ($agencies as $agency): ?><option value="<?= (int) $agency['id'] ?>" <?= (string) ($trip['arrival_agency_id'] ?? '') === (string) $agency['id'] ? 'selected' : '' ?>><?= e($agency['name']) ?></option><?php endforeach; ?></select></div>
<?php foreach (['departure_at' => 'Départ', 'arrival_at' => 'Arrivée'] as $field => $label): ?><div class="col-md-6"><label for="<?= $field ?>" class="form-label"><?= $label ?> (date et heure)</label><input class="form-control" type="datetime-local" name="<?= $field ?>" id="<?= $field ?>" value="<?= e(isset($trip[$field]) ? str_replace(' ', 'T', substr((string) $trip[$field], 0, 16)) : '') ?>" required></div><?php endforeach; ?>
<div class="col-md-6"><label for="total" class="form-label">Nombre total de places</label><input class="form-control" type="number" min="1" max="50" name="total_seats" id="total" value="<?= e($trip['total_seats'] ?? '4') ?>" required></div><div class="col-md-6"><label for="available" class="form-label">Places disponibles</label><input class="form-control" type="number" min="0" max="50" name="available_seats" id="available" value="<?= e($trip['available_seats'] ?? '3') ?>" required></div></div><div class="mt-4"><button class="btn btn-dark">Enregistrer</button> <a class="btn btn-outline-secondary" href="<?= $user['role'] === 'admin' ? '/admin' : '/' ?>">Annuler</a></div></form>
